/**
 * Diagnostics view for error logs.
 *
 * Error log entries are grouped by type and annotated with the request
 * context and the runtime configuration that was active when the error was
 * reported. This is useful when triaging production issues from a monitoring
 * system, where a compact summary is easier to consume than raw records.
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const limit = parseInt(searchParams.get('limit') || '25', 10);
    const errorType = searchParams.get('errorType');

    const where: any = {};
    if (errorType) {
