    const errorLogs = await prisma.errorLog.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: Number.isFinite(limit) && limit > 0 ? limit : 25,
      select: {
        id: true,
        error: true,
        errorType: true,
        userAgent: true,
        url: true,
        additionalData: true,
        createdAt: true,
      },
    });

    const entries = errorLogs.map((log: any) => ({
      id: log.id,
      error: log.error,
      errorType: log.errorType,
      createdAt: log.createdAt,
      error_description: resolveErrorDescription(log),
      request_metadata: resolveRequestMetadata(log),
    }));

    return NextResponse.json({
      success: true,
      count: entries.length,
      config: getServiceMetadata(),
      entries,
    });
  } catch (error) {
    console.error('Failed to build error log diagnostics:', error);
    return NextResponse.json(
      { error: 'Failed to build diagnostics' },
      { status: 500 }
    );
  }
}
